// קוד C++ המיועד להיווצר בלייב:
void setup() {
  bot.begin();
}

void loop() {
  int distance = bot.getDistance();
  if (distance < 20) {
    bot.stop();
    bot.beep();
  } else {
    bot.moveForward(150);
  }
  delay(50);
}

